// Gerado a partir da pasta frontend/. Se o código mudar, este arquivo precisa ser atualizado.
window.FONTES = {
 "package.json": "{\n  \"name\": \"controle-de-estoque-frontend\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"@fontsource/ibm-plex-mono\": \"^5.1.0\",\n    \"@fontsource/ibm-plex-sans\": \"^5.1.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"react-router-dom\": \"^6.28.0\"\n  },\n  \"devDependencies\": {\n    \"@vitejs/plugin-react\": \"^4.3.4\",\n    \"vite\": \"^5.4.11\"\n  }\n}",
 "vite.config.js": "import { defineConfig } from 'vite';\nimport react from '@vitejs/plugin-react';\n\nconst BACKEND = 'http://localhost:8080';\n\nfunction configurarProxy(proxy) {\n  // Pelo proxy a chamada é de mesma origem; sem isso o CORS do Spring recusa origens como 127.0.0.1:5173\n  proxy.on('proxyReq', (proxyReq) => proxyReq.removeHeader('origin'));\n\n  // Com o backend fora do ar o proxy responde 502, e o front trata como erro de rede\n  proxy.on('error', (_erro, _req, res) => {\n    if (res.writeHead && !res.headersSent) {\n      res.writeHead(502, { 'Content-Type': 'text/plain; charset=utf-8' });\n      res.end('Backend indisponível');\n    }\n  });\n}\n\nconst rotaApi = { target: BACKEND, changeOrigin: true, configure: configurarProxy };\n\nexport default defineConfig({\n  plugins: [react()],\n  server: {\n    port: 5173,\n    proxy: {\n      '/mercadorias': rotaApi,\n      '/estoques': rotaApi,\n    },\n  },\n});",
 ".env.example": "# URL base do backend usada pelo frontend.\n# Em desenvolvimento deixe vazio: o Vite encaminha /mercadorias e /estoques para http://localhost:8080.\n# Em produção informe a URL real do backend, sem barra no final, e libere essa origem no CORS do backend\n# (propriedade app.cors.allowed-origins).\n# Exemplo: VITE_API_URL=https://api.meuestoque.com.br\nVITE_API_URL=",
 "index.html": "<!doctype html>\n<html lang=\"pt-BR\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta name=\"description\" content=\"Cadastro de mercadorias e controle de estoque.\" />\n    <title>Controle de Estoque</title>\n  </head>\n  <body>\n    <div id=\"raiz\"></div>\n    <script type=\"module\" src=\"/src/main.jsx\"></script>\n  </body>\n</html>",
 "src/main.jsx": "import { StrictMode } from 'react';\nimport { createRoot } from 'react-dom/client';\nimport '@fontsource/ibm-plex-sans/latin-400.css';\nimport '@fontsource/ibm-plex-sans/latin-600.css';\nimport '@fontsource/ibm-plex-mono/latin-400.css';\nimport './styles/tokens.css';\nimport './styles/base.css';\nimport './styles/componentes.css';\nimport App from './App.jsx';\n\ncreateRoot(document.getElementById('raiz')).render(\n  <StrictMode>\n    <App />\n  </StrictMode>,\n);",
 "src/App.jsx": "import { HashRouter, Route, Routes, useParams } from 'react-router-dom';\nimport Layout from './components/Layout.jsx';\nimport EstoqueForm from './pages/EstoqueForm.jsx';\nimport EstoquesLista from './pages/EstoquesLista.jsx';\nimport Inicio from './pages/Inicio.jsx';\nimport MercadoriaForm from './pages/MercadoriaForm.jsx';\nimport MercadoriasLista from './pages/MercadoriasLista.jsx';\nimport NaoEncontrada from './pages/NaoEncontrada.jsx';\n\n// Só abre a edição quando o id da URL é numérico, como o backend espera\nfunction ComIdNumerico({ children }) {\n  const { id } = useParams();\n  return /^\\d+$/.test(id) ? children : <NaoEncontrada />;\n}\n\nexport default function App() {\n  return (\n    <HashRouter>\n      <Routes>\n        <Route element={<Layout />}>\n          <Route index element={<Inicio />} />\n          <Route path=\"mercadorias\" element={<MercadoriasLista />} />\n          <Route path=\"mercadorias/nova\" element={<MercadoriaForm />} />\n          <Route path=\"mercadorias/:id/editar\" element={<ComIdNumerico><MercadoriaForm /></ComIdNumerico>} />\n          <Route path=\"estoques\" element={<EstoquesLista />} />\n          <Route path=\"estoques/novo\" element={<EstoqueForm />} />\n          <Route path=\"estoques/:id/editar\" element={<ComIdNumerico><EstoqueForm /></ComIdNumerico>} />\n          <Route path=\"*\" element={<NaoEncontrada />} />\n        </Route>\n      </Routes>\n    </HashRouter>\n  );\n}",
 "src/api/http.js": "const BASE = (import.meta.env.VITE_API_URL ?? '').replace(/\\/$/, '');\nconst ENDERECO_BACKEND = BASE ? BASE.replace(/^https?:\\/\\//, '') : 'localhost:8080';\n\nexport const MENSAGEM_REDE =\n  `Não foi possível falar com o servidor. Confira se o backend está rodando em ${ENDERECO_BACKEND}.`;\n\nexport class ErroApi extends Error {\n  constructor({ status, mensagem, campos = null }) {\n    super(mensagem);\n    this.status = status;\n    this.mensagem = mensagem;\n    this.campos = campos && Object.keys(campos).length ? campos : null;\n  }\n\n  get rede() {\n    return this.status === 0;\n  }\n}\n\nasync function lerJson(resposta) {\n  const tipo = resposta.headers.get('Content-Type') ?? '';\n  if (!tipo.includes('json')) return null;\n  try {\n    return await resposta.json();\n  } catch {\n    return null;\n  }\n}\n\nexport async function requisitar(caminho, { metodo = 'GET', corpo } = {}) {\n  let resposta;\n  try {\n    resposta = await fetch(BASE + caminho, {\n      method: metodo,\n      headers: corpo ? { 'Content-Type': 'application/json' } : undefined,\n      body: corpo ? JSON.stringify(corpo) : undefined,\n    });\n  } catch {\n    throw new ErroApi({ status: 0, mensagem: MENSAGEM_REDE });\n  }\n\n  if (resposta.status === 204) return null;\n\n  const dados = await lerJson(resposta);\n  if (resposta.ok) return dados;\n\n  // Sem corpo JSON em 502, 503 ou 504: o backend não respondeu (proxy ou gateway)\n  if (!dados && [502, 503, 504].includes(resposta.status)) {\n    throw new ErroApi({ status: 0, mensagem: MENSAGEM_REDE });\n  }\n\n  throw new ErroApi({\n    status: resposta.status,\n    mensagem: dados?.mensagem ?? `O servidor recusou a operação (erro ${resposta.status}).`,\n    campos: dados?.campos,\n  });\n}",
 "src/api/mercadorias.js": "import { requisitar } from './http.js';\n\nexport const listarMercadorias = () => requisitar('/mercadorias');\nexport const buscarMercadoria = (id) => requisitar(`/mercadorias/${id}`);\nexport const criarMercadoria = (dados) => requisitar('/mercadorias', { metodo: 'POST', corpo: dados });\nexport const atualizarMercadoria = (id, dados) =>\n  requisitar(`/mercadorias/${id}`, { metodo: 'PUT', corpo: dados });\nexport const excluirMercadoria = (id) => requisitar(`/mercadorias/${id}`, { metodo: 'DELETE' });",
 "src/api/estoques.js": "import { requisitar } from './http.js';\n\nexport const listarEstoques = () => requisitar('/estoques');\nexport const buscarEstoque = (id) => requisitar(`/estoques/${id}`);\nexport const criarEstoque = (dados) => requisitar('/estoques', { metodo: 'POST', corpo: dados });\nexport const atualizarEstoque = (id, dados) =>\n  requisitar(`/estoques/${id}`, { metodo: 'PUT', corpo: dados });\nexport const excluirEstoque = (id) => requisitar(`/estoques/${id}`, { metodo: 'DELETE' });",
 "src/lib/hooks.js": "import { useCallback, useEffect, useRef, useState } from 'react';\nimport { useLocation, useNavigate } from 'react-router-dom';\n\nexport function useTitulo(titulo) {\n  useEffect(() => {\n    document.title = `${titulo} | Controle de Estoque`;\n  }, [titulo]);\n}\n\n// Carrega dados ao montar e sempre que a chave muda; recarregar() refaz a requisição\nexport function useCarregar(carregar, chave = '') {\n  const carregarRef = useRef(carregar);\n  carregarRef.current = carregar;\n  const [tentativa, setTentativa] = useState(0);\n  const [estado, setEstado] = useState({ status: 'carregando', dados: null, erro: null });\n\n  useEffect(() => {\n    let ativo = true;\n    setEstado({ status: 'carregando', dados: null, erro: null });\n    carregarRef.current().then(\n      (dados) => ativo && setEstado({ status: 'pronto', dados, erro: null }),\n      (erro) => ativo && setEstado({ status: 'erro', dados: null, erro }),\n    );\n    return () => {\n      ativo = false;\n    };\n  }, [chave, tentativa]);\n\n  const recarregar = useCallback(() => setTentativa((n) => n + 1), []);\n  const alterarDados = useCallback(\n    (alterar) => setEstado((atual) => ({ ...atual, dados: alterar(atual.dados) })),\n    [],\n  );\n\n  return { ...estado, recarregar, alterarDados };\n}\n\n// Lê o aviso enviado por navigate(..., { state: { aviso } }) e limpa o histórico\nexport function useAviso() {\n  const location = useLocation();\n  const navigate = useNavigate();\n  const [aviso, setAviso] = useState(location.state?.aviso ?? null);\n\n  useEffect(() => {\n    if (location.state?.aviso) {\n      navigate({ pathname: location.pathname, search: location.search }, { replace: true, state: null });\n    }\n    // Só na montagem: o aviso vale para a chegada na tela\n  }, []);\n\n  return [aviso, setAviso];\n}",
 "src/lib/validar.js": "const MAIOR_INTEIRO = 2147483647;\n\nexport const lerPreco = (texto) => Number(texto.trim().replace(',', '.'));\n\nfunction validarTexto(valor, rotulo, obrigatorioMsg) {\n  const texto = valor.trim();\n  if (!texto) return obrigatorioMsg;\n  if (texto.length > 100) return `${rotulo} deve ter no máximo 100 caracteres`;\n  return null;\n}\n\nfunction validarInteiro(valor, obrigatorioMsg, negativoMsg) {\n  const texto = valor.trim();\n  if (!texto) return obrigatorioMsg;\n  if (/^-\\d/.test(texto)) return negativoMsg;\n  if (!/^\\d+$/.test(texto)) return 'Informe um número inteiro, sem vírgula ou ponto';\n  if (Number(texto) > MAIOR_INTEIRO) return 'O valor informado é grande demais';\n  return null;\n}\n\nfunction semVazios(erros) {\n  return Object.fromEntries(Object.entries(erros).filter(([, msg]) => msg));\n}\n\nexport function validarMercadoria({ nome, preco }) {\n  const texto = preco.trim();\n  let erroPreco = null;\n  if (!texto) erroPreco = 'O preço é obrigatório';\n  else if (/^-\\d/.test(texto)) erroPreco = 'O preço não pode ser negativo';\n  else if (!/^\\d+([.,]\\d+)?$/.test(texto)) erroPreco = 'Informe o preço só com números, por exemplo 25,90';\n  else if (!/^\\d{1,8}([.,]\\d{1,2})?$/.test(texto))\n    erroPreco = 'O preço deve ter no máximo 8 dígitos inteiros e 2 decimais';\n\n  return semVazios({\n    nome: validarTexto(nome, 'O nome', 'O nome é obrigatório'),\n    preco: erroPreco,\n  });\n}\n\nexport function validarEstoque(valores) {\n  const erros = {\n    idMerc: valores.idMerc ? null : 'Selecione a mercadoria',\n    quantidade: validarInteiro(\n      valores.quantidade,\n      'A quantidade é obrigatória',\n      'A quantidade não pode ser negativa',\n    ),\n    quantidadeMinima: validarInteiro(\n      valores.quantidadeMinima,\n      'A quantidade mínima é obrigatória',\n      'A quantidade mínima não pode ser negativa',\n    ),\n    quantidadeMaxima: validarInteiro(\n      valores.quantidadeMaxima,\n      'A quantidade máxima é obrigatória',\n      'A quantidade máxima não pode ser negativa',\n    ),\n    localizacao: validarTexto(valores.localizacao, 'A localização', 'A localização é obrigatória'),\n  };\n\n  if (!erros.quantidadeMinima && !erros.quantidadeMaxima &&\n      Number(valores.quantidadeMaxima) < Number(valores.quantidadeMinima)) {\n    erros.quantidadeMaxima = 'A quantidade máxima não pode ser menor que a quantidade mínima';\n  }\n\n  return semVazios(erros);\n}\n\n// Espera o React aplicar aria-invalid antes de mover o foco\nexport function focarPrimeiroInvalido(formulario) {\n  requestAnimationFrame(() => {\n    formulario?.querySelector('[aria-invalid=\"true\"]')?.focus();\n  });\n}",
 "src/lib/formatar.js": "const moeda = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });\nconst inteiro = new Intl.NumberFormat('pt-BR');\n\nexport const formatarMoeda = (valor) => moeda.format(Number(valor));\nexport const formatarInteiro = (valor) => inteiro.format(valor);\n\nexport function contar(quantidade, singular, plural) {\n  return `${formatarInteiro(quantidade)} ${quantidade === 1 ? singular : plural}`;\n}\n\n// 25.9 vira \"25,90\" para edição no formulário\nexport const precoParaTexto = (valor) => Number(valor).toFixed(2).replace('.', ',');",
 "src/lib/situacao.js": "export const ROTULOS_SITUACAO = {\n  abaixo: 'Abaixo do mínimo',\n  faixa: 'Dentro da faixa',\n  acima: 'Acima do máximo',\n};\n\nexport function situacaoDe({ quantidade, quantidadeMinima, quantidadeMaxima }) {\n  if (quantidade < quantidadeMinima) return 'abaixo';\n  if (quantidade > quantidadeMaxima) return 'acima';\n  return 'faixa';\n}",
 "src/components/Layout.jsx": "import { useEffect, useRef } from 'react';\nimport { Link, NavLink, Outlet, useLocation } from 'react-router-dom';\n\nexport default function Layout() {\n  const { pathname } = useLocation();\n  const conteudoRef = useRef(null);\n  const caminhoAnterior = useRef(pathname);\n\n  // Ao trocar de tela, leva o foco ao título para o leitor de tela anunciar a página nova\n  useEffect(() => {\n    if (caminhoAnterior.current === pathname) return;\n    caminhoAnterior.current = pathname;\n    conteudoRef.current?.querySelector('h1')?.focus();\n  }, [pathname]);\n\n  function pularParaConteudo(evento) {\n    evento.preventDefault();\n    conteudoRef.current?.querySelector('h1')?.focus();\n  }\n\n  return (\n    <>\n      <a className=\"pular\" href=\"#conteudo\" onClick={pularParaConteudo}>\n        Pular para o conteúdo\n      </a>\n      <header className=\"topo\">\n        <div className=\"topo-interno\">\n          <Link className=\"marca\" to=\"/\">\n            Controle de Estoque\n          </Link>\n          <nav aria-label=\"Principal\">\n            <ul className=\"nav\">\n              <li>\n                <NavLink to=\"/mercadorias\">Mercadorias</NavLink>\n              </li>\n              <li>\n                <NavLink to=\"/estoques\">Estoques</NavLink>\n              </li>\n            </ul>\n          </nav>\n        </div>\n      </header>\n      <main id=\"conteudo\" className=\"conteudo\" ref={conteudoRef}>\n        <Outlet />\n      </main>\n    </>\n  );\n}",
 "src/components/Campo.jsx": "export default function Campo({ id, rotulo, erro, dica, como: Controle = 'input', children, ...props }) {\n  const idDica = `${id}-dica`;\n  const idErro = `${id}-erro`;\n  const descricao = [dica && idDica, erro && idErro].filter(Boolean).join(' ') || undefined;\n\n  return (\n    <div className=\"campo\">\n      <label htmlFor={id}>{rotulo}</label>\n      {dica && (\n        <p id={idDica} className=\"campo-dica\">\n          {dica}\n        </p>\n      )}\n      <Controle\n        id={id}\n        name={id}\n        className=\"controle\"\n        aria-invalid={erro ? true : undefined}\n        aria-describedby={descricao}\n        {...props}\n      >\n        {children}\n      </Controle>\n      {erro && (\n        <p id={idErro} className=\"campo-erro\">\n          {erro}\n        </p>\n      )}\n    </div>\n  );\n}",
 "src/components/Alerta.jsx": "import { useEffect, useState } from 'react';\n\n// As duas regiões ficam sempre no DOM; o texto entra depois para ser anunciado\nexport default function Alerta({ aviso, onFechar }) {\n  const [exibido, setExibido] = useState(null);\n\n  useEffect(() => {\n    setExibido(null);\n    if (!aviso) return undefined;\n    const tempo = setTimeout(() => setExibido(aviso), 60);\n    return () => clearTimeout(tempo);\n  }, [aviso]);\n\n  const conteudo = (tipo) =>\n    exibido?.tipo === tipo && (\n      <div className={`alerta alerta-${tipo}`}>\n        <p>{exibido.texto}</p>\n        {onFechar && (\n          <button type=\"button\" className=\"botao-texto\" onClick={onFechar}>\n            Fechar aviso\n          </button>\n        )}\n      </div>\n    );\n\n  return (\n    <>\n      <div role=\"status\">{conteudo('sucesso')}</div>\n      <div role=\"alert\">{conteudo('erro')}</div>\n    </>\n  );\n}",
 "src/components/ConfirmarExclusao.jsx": "import { useEffect, useRef } from 'react';\n\nexport default function ConfirmarExclusao({ aberto, titulo, mensagem, enviando, onConfirmar, onCancelar }) {\n  const dialogoRef = useRef(null);\n  const cancelarRef = useRef(null);\n\n  useEffect(() => {\n    const dialogo = dialogoRef.current;\n    if (aberto && !dialogo.open) {\n      dialogo.showModal();\n      cancelarRef.current.focus();\n    } else if (!aberto && dialogo.open) {\n      dialogo.close();\n    }\n  }, [aberto]);\n\n  function aoCancelarPeloTeclado(evento) {\n    evento.preventDefault();\n    if (!enviando) onCancelar();\n  }\n\n  return (\n    <dialog\n      ref={dialogoRef}\n      className=\"dialogo\"\n      aria-labelledby=\"dialogo-titulo\"\n      aria-describedby=\"dialogo-mensagem\"\n      onCancel={aoCancelarPeloTeclado}\n    >\n      <h2 id=\"dialogo-titulo\">{titulo}</h2>\n      <p id=\"dialogo-mensagem\">{mensagem}</p>\n      <div className=\"dialogo-acoes\">\n        <button ref={cancelarRef} type=\"button\" className=\"botao\" onClick={onCancelar} disabled={enviando}>\n          Cancelar\n        </button>\n        <button type=\"button\" className=\"botao botao-perigo-cheio\" onClick={onConfirmar} disabled={enviando}>\n          {enviando ? 'Excluindo...' : 'Excluir'}\n        </button>\n      </div>\n    </dialog>\n  );\n}",
 "src/components/Carregando.jsx": "export default function Carregando({ texto }) {\n  return (\n    <p className=\"carregando\" role=\"status\">\n      {texto}\n    </p>\n  );\n}",
 "src/components/EstadoErro.jsx": "export default function EstadoErro({ erro, onTentar, children }) {\n  const podeTentar = onTentar && erro?.status !== 404;\n\n  return (\n    <div className=\"estado-erro\" role=\"alert\">\n      <p>{erro?.mensagem ?? 'Ocorreu um erro inesperado ao carregar os dados.'}</p>\n      <div className=\"linha-acoes\">\n        {podeTentar && (\n          <button type=\"button\" className=\"botao\" onClick={onTentar}>\n            Tentar de novo\n          </button>\n        )}\n        {children}\n      </div>\n    </div>\n  );\n}",
 "src/components/EstadoVazio.jsx": "export default function EstadoVazio({ texto, children }) {\n  return (\n    <div className=\"estado-vazio\">\n      <p>{texto}</p>\n      {children}\n    </div>\n  );\n}",
 "src/pages/Inicio.jsx": "import { Link } from 'react-router-dom';\nimport { listarEstoques } from '../api/estoques.js';\nimport { listarMercadorias } from '../api/mercadorias.js';\nimport EstadoErro from '../components/EstadoErro.jsx';\nimport { contar, formatarInteiro } from '../lib/formatar.js';\nimport { useCarregar, useTitulo } from '../lib/hooks.js';\nimport { situacaoDe } from '../lib/situacao.js';\n\nconst carregarResumo = () => Promise.all([listarMercadorias(), listarEstoques()]);\n\nconst ENTIDADES = [\n  { nome: 'Mercadorias', lista: '/mercadorias', cadastro: '/mercadorias/nova', rotuloCadastro: 'Cadastrar mercadoria' },\n  { nome: 'Estoques', lista: '/estoques', cadastro: '/estoques/novo', rotuloCadastro: 'Cadastrar estoque' },\n];\n\nexport default function Inicio() {\n  useTitulo('Início');\n  const resumo = useCarregar(carregarResumo);\n  const [mercadorias, estoques] = resumo.dados ?? [];\n  const totais = resumo.dados ? [mercadorias.length, estoques.length] : [];\n  const abaixo = estoques?.filter((e) => situacaoDe(e) === 'abaixo').length ?? 0;\n\n  function textoTotal(indice) {\n    if (resumo.status === 'carregando') return 'Carregando';\n    if (resumo.status === 'erro') return 'Indisponível';\n    return formatarInteiro(totais[indice]);\n  }\n\n  return (\n    <>\n      <div className=\"cabecalho-pagina\">\n        <h1 tabIndex={-1}>Início</h1>\n      </div>\n      <p className=\"texto-suave\">Cadastro de mercadorias e controle das quantidades guardadas em cada local.</p>\n\n      {resumo.status === 'erro' && <EstadoErro erro={resumo.erro} onTentar={resumo.recarregar} />}\n\n      <div className=\"tabela-rolagem\">\n        <table className=\"tabela\">\n          <caption>Registros por cadastro</caption>\n          <thead>\n            <tr>\n              <th scope=\"col\">Cadastro</th>\n              <th scope=\"col\" className=\"num\">Registros</th>\n              <th scope=\"col\" className=\"acoes\">Ações</th>\n            </tr>\n          </thead>\n          <tbody aria-busy={resumo.status === 'carregando'}>\n            {ENTIDADES.map((entidade, indice) => (\n              <tr key={entidade.nome}>\n                <th scope=\"row\">{entidade.nome}</th>\n                <td className=\"num\">{textoTotal(indice)}</td>\n                <td className=\"acoes\">\n                  <Link className=\"botao botao-pequeno\" to={entidade.lista} aria-label={`Ver lista de ${entidade.nome.toLowerCase()}`}>\n                    Ver lista\n                  </Link>\n                  <Link className=\"botao botao-pequeno\" to={entidade.cadastro} aria-label={entidade.rotuloCadastro}>\n                    Cadastrar\n                  </Link>\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </div>\n\n      {resumo.status === 'pronto' && (\n        <p className=\"linha-resumo\">\n          {abaixo === 0 ? (\n            <>\n              Nenhum estoque abaixo do mínimo. <Link to=\"/estoques\">Ver estoques</Link>\n            </>\n          ) : (\n            <>\n              <strong>{contar(abaixo, 'estoque está abaixo', 'estoques estão abaixo')} do mínimo.</strong>{' '}\n              <Link to=\"/estoques?situacao=abaixo\">Ver estoques abaixo do mínimo</Link>\n            </>\n          )}\n        </p>\n      )}\n    </>\n  );\n}",
 "src/pages/MercadoriasLista.jsx": "import { useRef, useState } from 'react';\nimport { Link } from 'react-router-dom';\nimport { excluirMercadoria, listarMercadorias } from '../api/mercadorias.js';\nimport Alerta from '../components/Alerta.jsx';\nimport Carregando from '../components/Carregando.jsx';\nimport ConfirmarExclusao from '../components/ConfirmarExclusao.jsx';\nimport EstadoErro from '../components/EstadoErro.jsx';\nimport EstadoVazio from '../components/EstadoVazio.jsx';\nimport { contar, formatarMoeda } from '../lib/formatar.js';\nimport { useAviso, useCarregar, useTitulo } from '../lib/hooks.js';\n\nexport default function MercadoriasLista() {\n  useTitulo('Mercadorias');\n  const tituloRef = useRef(null);\n  const [aviso, setAviso] = useAviso();\n  const lista = useCarregar(listarMercadorias);\n  const [alvo, setAlvo] = useState(null);\n  const [excluindo, setExcluindo] = useState(false);\n\n  async function confirmarExclusao() {\n    setExcluindo(true);\n    try {\n      await excluirMercadoria(alvo.id);\n      lista.alterarDados((dados) => dados.filter((m) => m.id !== alvo.id));\n      setAviso({ tipo: 'sucesso', texto: `Mercadoria '${alvo.nome}' excluída.` });\n      requestAnimationFrame(() => tituloRef.current?.focus());\n    } catch (erro) {\n      setAviso({ tipo: 'erro', texto: erro.mensagem });\n      if (erro.status === 404) lista.recarregar();\n    } finally {\n      setExcluindo(false);\n      setAlvo(null);\n    }\n  }\n\n  let conteudo;\n  if (lista.status === 'carregando') {\n    conteudo = <Carregando texto=\"Carregando mercadorias...\" />;\n  } else if (lista.status === 'erro') {\n    conteudo = <EstadoErro erro={lista.erro} onTentar={lista.recarregar} />;\n  } else if (lista.dados.length === 0) {\n    conteudo = (\n      <EstadoVazio texto=\"Nenhuma mercadoria cadastrada. Cadastre a primeira para poder criar estoques.\">\n        <Link to=\"/mercadorias/nova\">Cadastrar mercadoria</Link>\n      </EstadoVazio>\n    );\n  } else {\n    conteudo = (\n      <div className=\"tabela-rolagem\">\n        <table className=\"tabela\">\n          <caption>{contar(lista.dados.length, 'mercadoria cadastrada', 'mercadorias cadastradas')}</caption>\n          <thead>\n            <tr>\n              <th scope=\"col\" className=\"num\">Id</th>\n              <th scope=\"col\">Nome</th>\n              <th scope=\"col\" className=\"num\">Preço</th>\n              <th scope=\"col\" className=\"acoes\">Ações</th>\n            </tr>\n          </thead>\n          <tbody>\n            {lista.dados.map((mercadoria) => (\n              <tr key={mercadoria.id}>\n                <td className=\"num\">{mercadoria.id}</td>\n                <th scope=\"row\">{mercadoria.nome}</th>\n                <td className=\"num\">{formatarMoeda(mercadoria.preco)}</td>\n                <td className=\"acoes\">\n                  <Link\n                    className=\"botao botao-pequeno\"\n                    to={`/mercadorias/${mercadoria.id}/editar`}\n                    aria-label={`Editar ${mercadoria.nome}`}\n                  >\n                    Editar\n                  </Link>\n                  <button\n                    type=\"button\"\n                    className=\"botao botao-pequeno botao-perigo\"\n                    onClick={() => setAlvo(mercadoria)}\n                    aria-label={`Excluir ${mercadoria.nome}`}\n                  >\n                    Excluir\n                  </button>\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </div>\n    );\n  }\n\n  return (\n    <>\n      <div className=\"cabecalho-pagina\">\n        <h1 ref={tituloRef} tabIndex={-1}>Mercadorias</h1>\n        <Link className=\"botao botao-principal\" to=\"/mercadorias/nova\">\n          Nova mercadoria\n        </Link>\n      </div>\n      <Alerta aviso={aviso} onFechar={() => setAviso(null)} />\n      {conteudo}\n      <ConfirmarExclusao\n        aberto={Boolean(alvo)}\n        titulo=\"Excluir mercadoria\"\n        mensagem={alvo && `Excluir '${alvo.nome}'? Essa ação não pode ser desfeita.`}\n        enviando={excluindo}\n        onConfirmar={confirmarExclusao}\n        onCancelar={() => setAlvo(null)}\n      />\n    </>\n  );\n}",
 "src/pages/MercadoriaForm.jsx": "import { useEffect, useRef, useState } from 'react';\nimport { Link, useNavigate, useParams } from 'react-router-dom';\nimport { atualizarMercadoria, buscarMercadoria, criarMercadoria } from '../api/mercadorias.js';\nimport Alerta from '../components/Alerta.jsx';\nimport Campo from '../components/Campo.jsx';\nimport Carregando from '../components/Carregando.jsx';\nimport EstadoErro from '../components/EstadoErro.jsx';\nimport { precoParaTexto } from '../lib/formatar.js';\nimport { useCarregar, useTitulo } from '../lib/hooks.js';\nimport { focarPrimeiroInvalido, lerPreco, validarMercadoria } from '../lib/validar.js';\n\nconst VAZIO = { nome: '', preco: '' };\n\nexport default function MercadoriaForm() {\n  const { id } = useParams();\n  const edicao = id !== undefined;\n  const titulo = edicao ? 'Editar mercadoria' : 'Nova mercadoria';\n  useTitulo(titulo);\n\n  const navigate = useNavigate();\n  const formRef = useRef(null);\n  const [valores, setValores] = useState(VAZIO);\n  const [erros, setErros] = useState({});\n  const [aviso, setAviso] = useState(null);\n  const [enviando, setEnviando] = useState(false);\n  const carga = useCarregar(() => (edicao ? buscarMercadoria(id) : Promise.resolve(null)), id);\n\n  useEffect(() => {\n    if (carga.dados) setValores({ nome: carga.dados.nome, preco: precoParaTexto(carga.dados.preco) });\n  }, [carga.dados]);\n\n  function alterar(evento) {\n    const { name, value } = evento.target;\n    setValores((atuais) => ({ ...atuais, [name]: value }));\n    setErros(({ [name]: _removido, ...resto }) => resto);\n  }\n\n  async function salvar(evento) {\n    evento.preventDefault();\n    setAviso(null);\n    const errosCliente = validarMercadoria(valores);\n    setErros(errosCliente);\n    if (Object.keys(errosCliente).length) {\n      focarPrimeiroInvalido(formRef.current);\n      return;\n    }\n\n    setEnviando(true);\n    const corpo = { nome: valores.nome.trim(), preco: lerPreco(valores.preco) };\n    try {\n      const salva = edicao ? await atualizarMercadoria(id, corpo) : await criarMercadoria(corpo);\n      const acao = edicao ? 'alterada' : 'cadastrada';\n      navigate('/mercadorias', { state: { aviso: { tipo: 'sucesso', texto: `Mercadoria '${salva.nome}' ${acao}.` } } });\n    } catch (erro) {\n      setEnviando(false);\n      if (erro.campos) {\n        setErros(erro.campos);\n        focarPrimeiroInvalido(formRef.current);\n      }\n      setAviso({ tipo: 'erro', texto: erro.campos ? `${erro.mensagem}. Revise os campos indicados.` : erro.mensagem });\n    }\n  }\n\n  let conteudo;\n  if (carga.status === 'carregando') {\n    conteudo = <Carregando texto=\"Carregando mercadoria...\" />;\n  } else if (carga.status === 'erro') {\n    conteudo = (\n      <EstadoErro erro={carga.erro} onTentar={carga.recarregar}>\n        <Link to=\"/mercadorias\">Voltar para a lista</Link>\n      </EstadoErro>\n    );\n  } else {\n    conteudo = (\n      <form ref={formRef} className=\"formulario\" onSubmit={salvar} noValidate>\n        <Campo id=\"nome\" rotulo=\"Nome\" value={valores.nome} onChange={alterar} erro={erros.nome} autoComplete=\"off\" />\n        <Campo\n          id=\"preco\"\n          rotulo=\"Preço (R$)\"\n          dica=\"Use vírgula ou ponto para os centavos, por exemplo 25,90.\"\n          value={valores.preco}\n          onChange={alterar}\n          erro={erros.preco}\n          inputMode=\"decimal\"\n          autoComplete=\"off\"\n          className=\"controle controle-numero\"\n        />\n        <div className=\"linha-acoes\">\n          <button type=\"submit\" className=\"botao botao-principal\" disabled={enviando}>\n            {enviando ? 'Salvando...' : 'Salvar mercadoria'}\n          </button>\n          <Link className=\"botao\" to=\"/mercadorias\">\n            Cancelar\n          </Link>\n        </div>\n      </form>\n    );\n  }\n\n  return (\n    <>\n      <div className=\"cabecalho-pagina\">\n        <h1 tabIndex={-1}>{titulo}</h1>\n        {edicao && <span className=\"identificador\">Id {id}</span>}\n      </div>\n      <Alerta aviso={aviso} />\n      {conteudo}\n    </>\n  );\n}",
 "src/pages/EstoquesLista.jsx": "import { useRef, useState } from 'react';\nimport { Link, useSearchParams } from 'react-router-dom';\nimport { excluirEstoque, listarEstoques } from '../api/estoques.js';\nimport Alerta from '../components/Alerta.jsx';\nimport Carregando from '../components/Carregando.jsx';\nimport ConfirmarExclusao from '../components/ConfirmarExclusao.jsx';\nimport EstadoErro from '../components/EstadoErro.jsx';\nimport EstadoVazio from '../components/EstadoVazio.jsx';\nimport { contar, formatarInteiro } from '../lib/formatar.js';\nimport { useAviso, useCarregar, useTitulo } from '../lib/hooks.js';\nimport { ROTULOS_SITUACAO, situacaoDe } from '../lib/situacao.js';\n\nexport default function EstoquesLista() {\n  useTitulo('Estoques');\n  const tituloRef = useRef(null);\n  const [parametros] = useSearchParams();\n  const soAbaixo = parametros.get('situacao') === 'abaixo';\n  const [aviso, setAviso] = useAviso();\n  const lista = useCarregar(listarEstoques);\n  const [alvo, setAlvo] = useState(null);\n  const [excluindo, setExcluindo] = useState(false);\n\n  async function confirmarExclusao() {\n    setExcluindo(true);\n    try {\n      await excluirEstoque(alvo.id);\n      lista.alterarDados((dados) => dados.filter((e) => e.id !== alvo.id));\n      setAviso({\n        tipo: 'sucesso',\n        texto: `Estoque de '${alvo.nomeMercadoria}' em '${alvo.localizacao}' excluído.`,\n      });\n      requestAnimationFrame(() => tituloRef.current?.focus());\n    } catch (erro) {\n      setAviso({ tipo: 'erro', texto: erro.mensagem });\n      if (erro.status === 404) lista.recarregar();\n    } finally {\n      setExcluindo(false);\n      setAlvo(null);\n    }\n  }\n\n  const visiveis = lista.dados?.filter((e) => !soAbaixo || situacaoDe(e) === 'abaixo') ?? [];\n\n  let conteudo;\n  if (lista.status === 'carregando') {\n    conteudo = <Carregando texto=\"Carregando estoques...\" />;\n  } else if (lista.status === 'erro') {\n    conteudo = <EstadoErro erro={lista.erro} onTentar={lista.recarregar} />;\n  } else if (lista.dados.length === 0) {\n    conteudo = (\n      <EstadoVazio texto=\"Nenhum estoque cadastrado. Cada estoque liga uma mercadoria a um local e às quantidades mínima e máxima.\">\n        <Link to=\"/estoques/novo\">Cadastrar estoque</Link>\n      </EstadoVazio>\n    );\n  } else if (visiveis.length === 0) {\n    conteudo = (\n      <EstadoVazio texto=\"Nenhum estoque abaixo do mínimo.\">\n        <Link to=\"/estoques\">Mostrar todos os estoques</Link>\n      </EstadoVazio>\n    );\n  } else {\n    const legenda = soAbaixo\n      ? contar(visiveis.length, 'estoque abaixo do mínimo', 'estoques abaixo do mínimo')\n      : contar(visiveis.length, 'estoque cadastrado', 'estoques cadastrados');\n\n    conteudo = (\n      <div className=\"tabela-rolagem\">\n        <table className=\"tabela\">\n          <caption>{legenda}</caption>\n          <thead>\n            <tr>\n              <th scope=\"col\">Mercadoria</th>\n              <th scope=\"col\" className=\"num\">Quantidade</th>\n              <th scope=\"col\" className=\"num\">Mínima</th>\n              <th scope=\"col\" className=\"num\">Máxima</th>\n              <th scope=\"col\">Localização</th>\n              <th scope=\"col\">Situação</th>\n              <th scope=\"col\" className=\"acoes\">Ações</th>\n            </tr>\n          </thead>\n          <tbody>\n            {visiveis.map((estoque) => {\n              const situacao = situacaoDe(estoque);\n              const descricao = `${estoque.nomeMercadoria} em ${estoque.localizacao}`;\n              return (\n                <tr key={estoque.id}>\n                  <th scope=\"row\">{estoque.nomeMercadoria}</th>\n                  <td className=\"num\">{formatarInteiro(estoque.quantidade)}</td>\n                  <td className=\"num\">{formatarInteiro(estoque.quantidadeMinima)}</td>\n                  <td className=\"num\">{formatarInteiro(estoque.quantidadeMaxima)}</td>\n                  <td>{estoque.localizacao}</td>\n                  <td className={`situacao situacao-${situacao}`}>{ROTULOS_SITUACAO[situacao]}</td>\n                  <td className=\"acoes\">\n                    <Link\n                      className=\"botao botao-pequeno\"\n                      to={`/estoques/${estoque.id}/editar`}\n                      aria-label={`Editar estoque de ${descricao}`}\n                    >\n                      Editar\n                    </Link>\n                    <button\n                      type=\"button\"\n                      className=\"botao botao-pequeno botao-perigo\"\n                      onClick={() => setAlvo(estoque)}\n                      aria-label={`Excluir estoque de ${descricao}`}\n                    >\n                      Excluir\n                    </button>\n                  </td>\n                </tr>\n              );\n            })}\n          </tbody>\n        </table>\n      </div>\n    );\n  }\n\n  return (\n    <>\n      <div className=\"cabecalho-pagina\">\n        <h1 ref={tituloRef} tabIndex={-1}>Estoques</h1>\n        <Link className=\"botao botao-principal\" to=\"/estoques/novo\">\n          Novo estoque\n        </Link>\n      </div>\n      {lista.status === 'pronto' && lista.dados.length > 0 && (\n        <p className=\"filtro\">\n          {soAbaixo ? (\n            <>\n              Mostrando só os estoques abaixo do mínimo. <Link to=\"/estoques\">Mostrar todos</Link>\n            </>\n          ) : (\n            <Link to=\"/estoques?situacao=abaixo\">Mostrar só os abaixo do mínimo</Link>\n          )}\n        </p>\n      )}\n      <Alerta aviso={aviso} onFechar={() => setAviso(null)} />\n      {conteudo}\n      <ConfirmarExclusao\n        aberto={Boolean(alvo)}\n        titulo=\"Excluir estoque\"\n        mensagem={\n          alvo &&\n          `Excluir o estoque de '${alvo.nomeMercadoria}' em '${alvo.localizacao}'? Essa ação não pode ser desfeita.`\n        }\n        enviando={excluindo}\n        onConfirmar={confirmarExclusao}\n        onCancelar={() => setAlvo(null)}\n      />\n    </>\n  );\n}",
 "src/pages/EstoqueForm.jsx": "import { useEffect, useRef, useState } from 'react';\nimport { Link, useNavigate, useParams } from 'react-router-dom';\nimport { atualizarEstoque, buscarEstoque, criarEstoque } from '../api/estoques.js';\nimport { listarMercadorias } from '../api/mercadorias.js';\nimport Alerta from '../components/Alerta.jsx';\nimport Campo from '../components/Campo.jsx';\nimport Carregando from '../components/Carregando.jsx';\nimport EstadoErro from '../components/EstadoErro.jsx';\nimport EstadoVazio from '../components/EstadoVazio.jsx';\nimport { useCarregar, useTitulo } from '../lib/hooks.js';\nimport { focarPrimeiroInvalido, validarEstoque } from '../lib/validar.js';\n\nconst VAZIO = { idMerc: '', quantidade: '', quantidadeMinima: '', quantidadeMaxima: '', localizacao: '' };\nconst CAMPOS_NUMERICOS = ['idMerc', 'quantidade', 'quantidadeMinima', 'quantidadeMaxima'];\n\nexport default function EstoqueForm() {\n  const { id } = useParams();\n  const edicao = id !== undefined;\n  const titulo = edicao ? 'Editar estoque' : 'Novo estoque';\n  useTitulo(titulo);\n\n  const navigate = useNavigate();\n  const formRef = useRef(null);\n  const [valores, setValores] = useState(VAZIO);\n  const [erros, setErros] = useState({});\n  const [aviso, setAviso] = useState(null);\n  const [enviando, setEnviando] = useState(false);\n  const carga = useCarregar(\n    () => Promise.all([listarMercadorias(), edicao ? buscarEstoque(id) : null]),\n    id,\n  );\n  const [mercadorias, estoque] = carga.dados ?? [[], null];\n\n  useEffect(() => {\n    if (!estoque) return;\n    setValores({\n      idMerc: String(estoque.idMerc),\n      quantidade: String(estoque.quantidade),\n      quantidadeMinima: String(estoque.quantidadeMinima),\n      quantidadeMaxima: String(estoque.quantidadeMaxima),\n      localizacao: estoque.localizacao,\n    });\n  }, [estoque]);\n\n  function alterar(evento) {\n    const { name, value } = evento.target;\n    setValores((atuais) => ({ ...atuais, [name]: value }));\n    setErros(({ [name]: _removido, ...resto }) => resto);\n  }\n\n  async function salvar(evento) {\n    evento.preventDefault();\n    setAviso(null);\n    const errosCliente = validarEstoque(valores);\n    setErros(errosCliente);\n    if (Object.keys(errosCliente).length) {\n      focarPrimeiroInvalido(formRef.current);\n      return;\n    }\n\n    setEnviando(true);\n    const corpo = { ...valores, localizacao: valores.localizacao.trim() };\n    CAMPOS_NUMERICOS.forEach((campo) => {\n      corpo[campo] = Number(valores[campo]);\n    });\n\n    try {\n      const salvo = edicao ? await atualizarEstoque(id, corpo) : await criarEstoque(corpo);\n      const acao = edicao ? 'alterado' : 'cadastrado';\n      const texto = `Estoque de '${salvo.nomeMercadoria}' em '${salvo.localizacao}' ${acao}.`;\n      navigate('/estoques', { state: { aviso: { tipo: 'sucesso', texto } } });\n    } catch (erro) {\n      setEnviando(false);\n      if (erro.campos) {\n        setErros(erro.campos);\n        focarPrimeiroInvalido(formRef.current);\n      }\n      setAviso({ tipo: 'erro', texto: erro.campos ? `${erro.mensagem}. Revise os campos indicados.` : erro.mensagem });\n    }\n  }\n\n  let conteudo;\n  if (carga.status === 'carregando') {\n    conteudo = <Carregando texto=\"Carregando dados do estoque...\" />;\n  } else if (carga.status === 'erro') {\n    conteudo = (\n      <EstadoErro erro={carga.erro} onTentar={carga.recarregar}>\n        <Link to=\"/estoques\">Voltar para a lista</Link>\n      </EstadoErro>\n    );\n  } else {\n    const semMercadorias = mercadorias.length === 0;\n    conteudo = (\n      <>\n        {semMercadorias && (\n          <EstadoVazio texto=\"Nenhuma mercadoria cadastrada. Cadastre a primeira para poder criar estoques.\">\n            <Link to=\"/mercadorias/nova\">Cadastrar mercadoria</Link>\n          </EstadoVazio>\n        )}\n        <form ref={formRef} className=\"formulario\" onSubmit={salvar} noValidate>\n          <fieldset className=\"grupo\" disabled={semMercadorias || enviando}>\n            <legend className=\"visualmente-oculto\">Dados do estoque</legend>\n            <Campo id=\"idMerc\" rotulo=\"Mercadoria\" como=\"select\" value={valores.idMerc} onChange={alterar} erro={erros.idMerc}>\n              <option value=\"\">Selecione a mercadoria</option>\n              {mercadorias.map((m) => (\n                <option key={m.id} value={m.id}>\n                  {m.nome} (id {m.id})\n                </option>\n              ))}\n            </Campo>\n            <Campo\n              id=\"quantidade\"\n              rotulo=\"Quantidade atual\"\n              value={valores.quantidade}\n              onChange={alterar}\n              erro={erros.quantidade}\n              inputMode=\"numeric\"\n              autoComplete=\"off\"\n              className=\"controle controle-numero\"\n            />\n            <Campo\n              id=\"quantidadeMinima\"\n              rotulo=\"Quantidade mínima\"\n              value={valores.quantidadeMinima}\n              onChange={alterar}\n              erro={erros.quantidadeMinima}\n              inputMode=\"numeric\"\n              autoComplete=\"off\"\n              className=\"controle controle-numero\"\n            />\n            <Campo\n              id=\"quantidadeMaxima\"\n              rotulo=\"Quantidade máxima\"\n              dica=\"Precisa ser igual ou maior que a quantidade mínima.\"\n              value={valores.quantidadeMaxima}\n              onChange={alterar}\n              erro={erros.quantidadeMaxima}\n              inputMode=\"numeric\"\n              autoComplete=\"off\"\n              className=\"controle controle-numero\"\n            />\n            <Campo\n              id=\"localizacao\"\n              rotulo=\"Localização\"\n              dica=\"Onde a mercadoria fica guardada, por exemplo Prateleira A1.\"\n              value={valores.localizacao}\n              onChange={alterar}\n              erro={erros.localizacao}\n              autoComplete=\"off\"\n            />\n            <div className=\"linha-acoes\">\n              <button type=\"submit\" className=\"botao botao-principal\">\n                {enviando ? 'Salvando...' : 'Salvar estoque'}\n              </button>\n              <Link className=\"botao\" to=\"/estoques\">\n                Cancelar\n              </Link>\n            </div>\n          </fieldset>\n        </form>\n      </>\n    );\n  }\n\n  return (\n    <>\n      <div className=\"cabecalho-pagina\">\n        <h1 tabIndex={-1}>{titulo}</h1>\n        {edicao && <span className=\"identificador\">Id {id}</span>}\n      </div>\n      <Alerta aviso={aviso} />\n      {conteudo}\n    </>\n  );\n}",
 "src/pages/NaoEncontrada.jsx": "import { Link } from 'react-router-dom';\nimport { useTitulo } from '../lib/hooks.js';\n\nexport default function NaoEncontrada() {\n  useTitulo('Página não encontrada');\n  return (\n    <>\n      <div className=\"cabecalho-pagina\">\n        <h1 tabIndex={-1}>Página não encontrada</h1>\n      </div>\n      <p>O endereço aberto não corresponde a nenhuma tela do sistema.</p>\n      <p>\n        <Link to=\"/\">Voltar para o início</Link>\n      </p>\n    </>\n  );\n}",
 "src/styles/tokens.css": ":root {\n  --cor-fundo: #f5f4f0;\n  --cor-superficie: #ffffff;\n  --cor-superficie-suave: #efede7;\n  --cor-linha-hover: #faf9f6;\n  --cor-borda: #d4d1c9;\n  --cor-borda-controle: #8a867c;\n  --cor-texto: #1c1d1b;\n  --cor-texto-suave: #57594f;\n  --cor-destaque: #0b5560;\n  --cor-destaque-escuro: #083f47;\n  --cor-destaque-fundo: #e5efef;\n  --cor-erro: #a8201a;\n  --cor-erro-escuro: #85170f;\n  --cor-erro-fundo: #fbeceb;\n  --cor-sobre-destaque: #ffffff;\n\n  --esp-1: 0.25rem;\n  --esp-2: 0.5rem;\n  --esp-3: 0.75rem;\n  --esp-4: 1rem;\n  --esp-5: 1.5rem;\n  --esp-6: 2rem;\n  --esp-7: 3rem;\n\n  --raio: 3px;\n  --largura-conteudo: 60rem;\n  --largura-formulario: 30rem;\n\n  --fonte-texto: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;\n  --fonte-mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Consolas, monospace;\n  --fs-pequeno: 0.875rem;\n  --fs-base: 1rem;\n  --fs-medio: 1.25rem;\n  --fs-grande: 1.75rem;\n}",
 "src/styles/base.css": "*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nhtml {\n  -webkit-text-size-adjust: 100%;\n}\n\nbody {\n  margin: 0;\n  background: var(--cor-fundo);\n  color: var(--cor-texto);\n  font-family: var(--fonte-texto);\n  font-size: var(--fs-base);\n  line-height: 1.5;\n}\n\nh1,\nh2,\np {\n  margin: 0;\n}\n\nh1 {\n  font-size: var(--fs-grande);\n  font-weight: 600;\n  line-height: 1.25;\n}\n\nh2 {\n  font-size: var(--fs-medio);\n  font-weight: 600;\n  line-height: 1.3;\n}\n\nstrong {\n  font-weight: 600;\n}\n\na {\n  color: var(--cor-destaque);\n  text-underline-offset: 0.15em;\n}\n\na:hover {\n  color: var(--cor-destaque-escuro);\n}\n\nbutton,\ninput,\nselect {\n  font: inherit;\n  color: inherit;\n}\n\n:focus-visible {\n  outline: 2px solid var(--cor-destaque);\n  outline-offset: 2px;\n}\n\n/* Alvos de foco programático (títulos) não precisam de contorno */\n[tabindex='-1']:focus {\n  outline: none;\n}\n\n.visualmente-oculto {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n.texto-suave {\n  color: var(--cor-texto-suave);\n}",
 "src/styles/componentes.css": "/* Estrutura */\n.pular {\n  position: absolute;\n  left: var(--esp-4);\n  top: -3rem;\n  padding: var(--esp-2) var(--esp-3);\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda-controle);\n  border-radius: var(--raio);\n  z-index: 10;\n}\n\n.pular:focus {\n  top: var(--esp-2);\n}\n\n.topo {\n  background: var(--cor-superficie);\n  border-bottom: 1px solid var(--cor-borda);\n}\n\n.topo-interno {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--esp-2) var(--esp-5);\n  max-width: var(--largura-conteudo);\n  margin: 0 auto;\n  padding: 0 var(--esp-4);\n}\n\n.marca {\n  padding: var(--esp-3) 0;\n  color: var(--cor-texto);\n  font-weight: 600;\n  text-decoration: none;\n}\n\n.marca:hover {\n  color: var(--cor-texto);\n  text-decoration: underline;\n}\n\n.nav {\n  display: flex;\n  gap: var(--esp-5);\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.nav a {\n  display: block;\n  padding: var(--esp-3) 0;\n  border-bottom: 2px solid transparent;\n  text-decoration: none;\n}\n\n.nav a:hover {\n  text-decoration: underline;\n}\n\n.nav a[aria-current='page'] {\n  color: var(--cor-texto);\n  font-weight: 600;\n  border-bottom-color: var(--cor-destaque);\n}\n\n.conteudo {\n  max-width: var(--largura-conteudo);\n  margin: 0 auto;\n  padding: var(--esp-6) var(--esp-4) var(--esp-7);\n}\n\n.cabecalho-pagina {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: var(--esp-3);\n  margin-bottom: var(--esp-4);\n}\n\n.cabecalho-pagina + .texto-suave {\n  margin: calc(-1 * var(--esp-2)) 0 var(--esp-5);\n}\n\n.identificador {\n  color: var(--cor-texto-suave);\n  font-family: var(--fonte-mono);\n  font-size: var(--fs-pequeno);\n}\n\n.linha-acoes {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--esp-3);\n}\n\n/* Botões */\n.botao {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 2.5rem;\n  padding: 0 var(--esp-4);\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda-controle);\n  border-radius: var(--raio);\n  color: var(--cor-texto);\n  font-weight: 600;\n  line-height: 1.2;\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.botao:hover {\n  background: var(--cor-superficie-suave);\n  color: var(--cor-texto);\n}\n\n.botao:disabled {\n  cursor: not-allowed;\n  opacity: 0.6;\n}\n\n.botao-principal {\n  background: var(--cor-destaque);\n  border-color: var(--cor-destaque);\n  color: var(--cor-sobre-destaque);\n}\n\n.botao-principal:hover {\n  background: var(--cor-destaque-escuro);\n  border-color: var(--cor-destaque-escuro);\n  color: var(--cor-sobre-destaque);\n}\n\n.botao-perigo {\n  border-color: var(--cor-erro);\n  color: var(--cor-erro);\n}\n\n.botao-perigo:hover {\n  background: var(--cor-erro-fundo);\n  color: var(--cor-erro-escuro);\n}\n\n.botao-perigo-cheio {\n  background: var(--cor-erro);\n  border-color: var(--cor-erro);\n  color: var(--cor-sobre-destaque);\n}\n\n.botao-perigo-cheio:hover {\n  background: var(--cor-erro-escuro);\n  border-color: var(--cor-erro-escuro);\n  color: var(--cor-sobre-destaque);\n}\n\n.botao-pequeno {\n  min-height: 2rem;\n  padding: 0 var(--esp-3);\n  font-size: var(--fs-pequeno);\n}\n\n.botao-texto {\n  padding: 0;\n  background: none;\n  border: 0;\n  color: inherit;\n  font-size: var(--fs-pequeno);\n  text-decoration: underline;\n  cursor: pointer;\n}\n\n/* Tabelas */\n.tabela-rolagem {\n  overflow-x: auto;\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda);\n  border-radius: var(--raio);\n}\n\n.tabela {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--fs-pequeno);\n}\n\n.tabela caption {\n  padding: var(--esp-3) var(--esp-3) var(--esp-2);\n  color: var(--cor-texto-suave);\n  text-align: left;\n}\n\n.tabela th,\n.tabela td {\n  padding: var(--esp-2) var(--esp-3);\n  border-top: 1px solid var(--cor-borda);\n  text-align: left;\n  vertical-align: middle;\n}\n\n.tabela thead th {\n  background: var(--cor-superficie-suave);\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.tabela tbody th {\n  font-weight: 600;\n}\n\n.tabela tbody tr:hover {\n  background: var(--cor-linha-hover);\n}\n\n.tabela .num {\n  font-family: var(--fonte-mono);\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  white-space: nowrap;\n}\n\n.tabela thead .num {\n  font-family: var(--fonte-texto);\n}\n\n.tabela .acoes {\n  text-align: right;\n  white-space: nowrap;\n}\n\n.tabela td.acoes > * + * {\n  margin-left: var(--esp-2);\n}\n\n.situacao {\n  white-space: nowrap;\n}\n\n.situacao-abaixo {\n  font-weight: 600;\n}\n\n.situacao-acima {\n  color: var(--cor-texto-suave);\n}\n\n.linha-resumo,\n.filtro {\n  margin-top: var(--esp-4);\n}\n\n.filtro {\n  margin: calc(-1 * var(--esp-2)) 0 var(--esp-4);\n  font-size: var(--fs-pequeno);\n}\n\n/* Avisos e estados */\n.alerta {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: var(--esp-2) var(--esp-4);\n  margin-bottom: var(--esp-4);\n  padding: var(--esp-3) var(--esp-4);\n  border: 1px solid;\n  border-left-width: 4px;\n  border-radius: var(--raio);\n}\n\n.alerta-sucesso {\n  background: var(--cor-destaque-fundo);\n  border-color: var(--cor-destaque);\n  color: var(--cor-destaque-escuro);\n}\n\n.alerta-erro {\n  background: var(--cor-erro-fundo);\n  border-color: var(--cor-erro);\n  color: var(--cor-erro-escuro);\n}\n\n.estado-vazio,\n.estado-erro,\n.carregando {\n  margin-bottom: var(--esp-4);\n  padding: var(--esp-5) var(--esp-4);\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda);\n  border-radius: var(--raio);\n}\n\n.estado-vazio p,\n.estado-erro p {\n  margin-bottom: var(--esp-3);\n}\n\n.estado-erro {\n  border-color: var(--cor-erro);\n}\n\n.estado-erro p {\n  color: var(--cor-erro-escuro);\n}\n\n.carregando {\n  color: var(--cor-texto-suave);\n}\n\n/* Formulários */\n.formulario {\n  max-width: var(--largura-formulario);\n  padding: var(--esp-5);\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda);\n  border-radius: var(--raio);\n}\n\n.grupo {\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 0;\n}\n\n.grupo:disabled .controle {\n  background: var(--cor-superficie-suave);\n  cursor: not-allowed;\n}\n\n.grupo:disabled .botao {\n  cursor: not-allowed;\n  opacity: 0.6;\n}\n\n.campo {\n  margin-bottom: var(--esp-5);\n}\n\n.campo label {\n  display: block;\n  margin-bottom: var(--esp-1);\n  font-weight: 600;\n}\n\n.campo-dica {\n  margin-bottom: var(--esp-2);\n  color: var(--cor-texto-suave);\n  font-size: var(--fs-pequeno);\n}\n\n.controle {\n  display: block;\n  width: 100%;\n  min-height: 2.5rem;\n  padding: var(--esp-2) var(--esp-3);\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda-controle);\n  border-radius: var(--raio);\n}\n\n.controle:hover {\n  border-color: var(--cor-texto-suave);\n}\n\n.controle:focus-visible {\n  outline-offset: 0;\n  border-color: var(--cor-destaque);\n}\n\n.controle[aria-invalid='true'] {\n  border-color: var(--cor-erro);\n  border-width: 2px;\n}\n\n.controle-numero {\n  max-width: 12rem;\n  font-family: var(--fonte-mono);\n  font-variant-numeric: tabular-nums;\n}\n\n.campo-erro {\n  margin-top: var(--esp-1);\n  color: var(--cor-erro);\n  font-size: var(--fs-pequeno);\n  font-weight: 600;\n}\n\n/* Diálogo de exclusão */\n.dialogo {\n  width: min(28rem, calc(100% - 2rem));\n  padding: var(--esp-5);\n  background: var(--cor-superficie);\n  border: 1px solid var(--cor-borda-controle);\n  border-radius: var(--raio);\n  color: var(--cor-texto);\n}\n\n.dialogo::backdrop {\n  background: rgb(28 29 27 / 0.45);\n}\n\n.dialogo p {\n  margin: var(--esp-3) 0 var(--esp-5);\n}\n\n.dialogo-acoes {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: var(--esp-3);\n}"
};
